def solve(n):
    """Count primes strictly less than n."""
    if n <= 2:
        return 0
    sieve = bytearray([1]) * n  # sieve[i] == 1 means i is (potentially) prime
    sieve[0] = 0
    sieve[1] = 0
    i = 2
    while i * i < n:
        if sieve[i]:
            step = i
            start = i * i
            sieve[start::step] = bytearray(len(range(start, n, step)))
        i += 1
    return sum(sieve)

