def solve(nums):
    import bisect
    tails = []  # tails[i] = smallest possible tail of an increasing subseq of length i+1
    for x in nums:
        # find position to replace in tails
        idx = bisect.bisect_left(tails, x)
        # ensure strictly increasing: use bisect_left (since we replace equal values, we don't allow equal to extend length)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

