def solve(path: str = None):
    """Simplify an absolute Unix path.
    If `path` is provided, return the simplified path.
    If called without arguments, read a line from stdin and print the result.
    """
    import sys
    if path is None:
        data = sys.stdin.read().splitlines()
        if not data:
            return
        path = data[0].strip()
    # Split by '/' and process components
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            # if stack empty, stay at root
        else:
            stack.append(part)
    simplified = '/' + '/'.join(stack)
    # Ensure no trailing slash except root
    if len(simplified) > 1 and simplified.endswith('/'):
        simplified = simplified.rstrip('/')
    if path is not None and (len(sys.argv) > 1 or sys.stdin.isatty()):
        # Called as a function in tests, return value
        return simplified
    else:
        # Called as script, print result
        print(simplified)

