def solve(s=None):
    """Validate IPv4 address.
    If `s` is provided (a string), returns True/False.
    If called without argument, reads one line from stdin and prints the result.
    """
    import sys
    if s is None:
        data = sys.stdin.read().splitlines()
        if not data:
            return
        s = data[0].strip()
    # Split into four parts
    parts = s.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part:
            return False
        if not part.isdigit():
            return False
        # No leading zeros unless the part is exactly "0"
        if len(part) > 1 and part[0] == '0':
            return False
        try:
            num = int(part)
        except ValueError:
            return False
        if num < 0 or num > 255:
            return False
    return True
