def solve(grid=None):
    """Count the number of islands in a binary grid.
    Parameters
    ----------
    grid : list of list of int or list of str, optional
        2‑D grid where 1 (or '1') represents land and 0 (or '0') water.
        If omitted, the function reads a single line from standard input
        containing a Python literal representation of the grid (e.g.
        "[[1,0],[0,1]]") and prints the result.
    Returns
    -------
    int
        Number of islands.
    """
    import sys, ast
    if grid is None:
        data = sys.stdin.read().strip()
        if not data:
            return
        try:
            grid = ast.literal_eval(data)
        except Exception:
            # fallback: empty grid
            grid = []
    # Normalize grid to list of lists of ints (0/1)
    if not grid:
        return 0
    # If grid is list of strings, convert each char
    if isinstance(grid[0], str):
        grid = [[1 if ch == '1' else 0 for ch in row] for row in grid]
    else:
        # ensure inner rows are lists of ints
        grid = [list(map(int, row)) for row in grid]
    rows, cols = len(grid), len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            x, y = stack.pop()
            if visited[x][y]:
                continue
            visited[x][y] = True
            for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                nx, ny = x+dx, y+dy
                if 0 <= nx < rows and 0 <= ny < cols and not visited[nx][ny] and grid[nx][ny] == 1:
                    stack.append((nx, ny))
    islands = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1 and not visited[i][j]:
                islands += 1
                dfs(i, j)
    return islands

