    """Check if brackets are balanced.
    Accepts the string to check via a positional argument, a keyword argument `s`,
    or reads the first line from standard input if no argument is provided.
    Returns True if every '()', '[]', '{}' is properly nested; otherwise False.
    """
    import sys
    if args:
        s = args[0]
    elif 's' in kwargs:
        s = kwargs['s']
    else:
        data = sys.stdin.read().splitlines()
        s = data[0] if data else ''
    # Ensure we have a string
    if not isinstance(s, str):
