def solve(meetings=None):
    """Return the maximum number of non‑overlapping meetings.
    If `meetings` is provided, it should be an iterable of [start, end]
    pairs (list or tuple). If omitted, the function reads a Python literal
    from standard input, evaluates it, and prints the result.
    """
    import sys, ast
    if meetings is None:
        data = sys.stdin.read().strip()
        if not data:
            return
        try:
            meetings = ast.literal_eval(data)
        except Exception:
            meetings = []
    if not meetings:
        return 0
    # Normalize to list of (start, end)
    norm = []
    for m in meetings:
        if isinstance(m, (list, tuple)) and len(m) == 2:
            s, e = m[0], m[1]
        else:
            raise ValueError("Invalid meeting format")
        norm.append((int(s), int(e)))
    # Sort by end time, then start
    norm.sort(key=lambda x: (x[1], x[0]))
    count = 0
    current_end = -float('inf')
    for s, e in norm:
        if s >= current_end:
            count += 1
            current_end = e
    return count

